import { loadAll } from 'js-yaml';
export const run = async ({ args, files }) => {
  const [source, target] = args;
  const documents = [];
  loadAll(files[source] ?? '', (document) => documents.push(document));
  const value = documents.length === 0 ? null : documents.length === 1 ? documents[0] : documents;
  const json = JSON.stringify(value, null, '  ') + '\n';
  return target === undefined ? { stdout: json, files: {} } : { stdout: '', files: { [target]: json } };
};
